import {apiRequest} from './api-client.js';
/** Full-page library management. Visibility, publishing and archive are separate operations. */
export async function openContentManager({modal,toast,openStudio,onBack}){
 modal('<div class="dialog-padding content-manager"><header><p class="eyebrow">AETHER / CONTENT LIBRARY</p><h2>Manage your stories.</h2><p>Published content stays published. Hide controls audience visibility; Delete moves content into the archive.</p><div class="video-actions"><button id="contentBack" class="button button-secondary">← Dashboard</button><button id="contentMovie" class="button button-primary">＋ New movie</button><button id="contentSeries" class="button button-secondary">＋ New series collection</button></div></header><div class="content-toolbar"><label>Find on this page<input id="contentSearch" type="search" placeholder="Title, series or content ID"></label><label>Content type<select id="contentKind"><option value="">All types</option><option value="films">Movies</option><option value="series">Series collections</option><option value="episode">Episodes</option></select></label><label>Status<select id="contentState"><option value="">All statuses</option><option>published</option><option>hidden</option><option>draft</option><option>processing</option><option>review</option><option>scheduled</option><option>archived</option></select></label></div><p id="contentMessage" role="status" aria-live="polite">Loading content…</p><div id="contentRows"></div><div class="video-actions"><button id="contentPrev" class="button button-secondary">← Previous 50</button><span id="contentPage"></span><button id="contentNext" class="button button-secondary">Next 50 →</button></div></div>','Content library');
 const root=document.querySelector('.content-manager'),get=id=>root.querySelector('#'+id);root.closest('.modal-dialog')?.classList.add('content-manager-dialog');if(!root.closest('#accountPage'))document.querySelector('#modal')?.classList.add('content-manager-shell');
 let page=0,titles=[],busy=false;
 const message=text=>get('contentMessage').textContent=text;
 const button=(label,fn,kind='secondary')=>{const b=document.createElement('button');b.type='button';b.className='button button-'+kind;b.textContent=label;b.disabled=busy;b.onclick=fn;return b;};
 const mutate=async(row,action)=>{if(busy)return;busy=true;render();message('Saving '+row.name+'…');try{await apiRequest('/api/admin/titles/'+row.id+(action==='delete'?'':action==='restore'?'/restore':'/visibility'),{method:action==='delete'?'DELETE':'POST',...(action==='hide'||action==='show'?{body:JSON.stringify({visible:action==='show'})}:{})});window.dispatchEvent(new Event('aether:catalog-changed'));await load();message(action==='delete'?'Moved to archive. Video files remain stored.':action==='restore'?'Restored. Previously published content returns as Hidden; use Show when ready.':action==='hide'?'Hidden from viewers. Published history and episode relationships are preserved.':'Shown to viewers when its parent series is also visible.');toast('Content updated');}catch(e){message(e.message);}finally{busy=false;render();}};
 const render=()=>{const area=get('contentRows');area.replaceChildren();const query=get('contentSearch').value.toLowerCase().trim(),kind=get('contentKind').value,state=get('contentState').value;const rows=titles.filter(t=>(!kind||t.kind===kind)&&(!state||t.status===state)&&(!query||[t.name,t.id,t.series_name,t.series_id].some(x=>String(x||'').toLowerCase().includes(query))));
 if(!rows.length){const p=document.createElement('p');p.className='notice';p.textContent='No matching content on this page.';area.append(p);}
 for(const row of rows){const card=document.createElement('article');card.className='content-record';card.dataset.contentKind=row.kind;const details=document.createElement('div'),badge=document.createElement('strong'),name=document.createElement('h3'),meta=document.createElement('p'),id=document.createElement('p');badge.className='status-sticker '+row.status;badge.textContent=row.status==='published'?'✓ PUBLISHED':row.status.toUpperCase();name.textContent=row.name;meta.textContent=row.kind==='episode'?`${row.series_name} · Season ${row.season_number} / Episode ${row.episode_number} · Series ID: ${row.series_id}`:row.kind==='series'?`Series collection · ${row.episode_count} episodes`:'Movie';id.className='content-id';id.textContent='Content ID: '+row.id;const type=document.createElement('span');type.className='content-type-badge';type.dataset.contentKind=row.kind;type.textContent=row.kind==='series'?'SERIES · COLLECTION':row.kind==='episode'?'EPISODE':'MOVIE';details.append(type,badge,name,meta,id);if(row.kind==='episode'&&row.status==='published'&&row.series_status!=='published'){const warning=document.createElement('p');warning.className='notice';warning.textContent='This episode is published but its parent series is '+row.series_status+'. Show or publish the parent series to make it visible.';details.append(warning);}const actions=document.createElement('div');actions.className='video-actions';if(row.status==='archived')actions.append(button('Restore',()=>mutate(row,'restore')));else{
 if(row.kind==='series')actions.append(button('＋ Add episode',()=>openStudio({intent:'episode',seriesId:row.id}),'primary'));
 if(row.status==='published'||row.status==='hidden')actions.append(button(row.status==='hidden'?'Show':'Hide',()=>mutate(row,row.status==='hidden'?'show':'hide')));
 else actions.append(button(row.status==='scheduled'?'Manage release':'Continue publishing',()=>openStudio({titleId:row.id}),'primary'));
 actions.append(button('Delete',()=>{const note=document.createElement('p');note.textContent=row.kind==='series'?'Archive this collection? Archive its episodes first. Files and history remain stored.':'Move this title to the archive? It disappears from the catalog. Files and history remain stored.';actions.replaceChildren(note,button('Confirm archive',()=>mutate(row,'delete'),'danger'),button('Cancel',render));},'danger'));}
 card.append(details,actions);area.append(card);}
 get('contentPrev').disabled=busy||page===0;get('contentNext').disabled=busy||!hasMore;get('contentPage').textContent='Page '+(page+1)+' · '+titles.length+' records';};
 let hasMore=false;const load=async()=>{const data=await apiRequest('/api/admin/content?page='+page);if(!root.isConnected)return;titles=data.titles;hasMore=data.hasMore;render();message('Select a title below. New episodes always belong to the displayed series ID.');};
 const sync=()=>{if(root.isConnected)void load().catch(e=>message(e.message));else window.removeEventListener('aether:catalog-changed',sync);};window.addEventListener('aether:catalog-changed',sync);get('contentBack').onclick=onBack;get('contentMovie').onclick=()=>openStudio({intent:'films'});get('contentSeries').onclick=()=>openStudio({intent:'series'});for(const id of ['contentSearch','contentKind','contentState'])get(id).oninput=render;
 get('contentPrev').onclick=()=>{page--;void load().catch(e=>message(e.message));};get('contentNext').onclick=()=>{page++;void load().catch(e=>message(e.message));};try{await load();}catch(e){message(e.message);}
}
